// Firefly's airstrikes resolve at their marked landing points, independent of movement.
const r=(m,k)=>m.growth?.[k]||0;
const live=(e,a)=>a.hp>0&&(!a.boss||e.bossAwake);
const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
export function fireflyTarget(e,m,reach=720){const candidates=e.enemies.filter(a=>live(e,a)&&distance(a,m)<reach);let best=null,bestScore=-Infinity;for(const a of candidates){const score=candidates.reduce((n,b)=>n+(distance(a,b)<240?1:0),0)*100+(a.boss?120:0)-distance(a,m)*.035;if(score>bestScore){best=a;bestScore=score;}}return best;}
export function queueAirstrike(e,p,damage,radius,delay=.4,kind='missile',generation=0){e.fireflyBombs??=[];if(e.fireflyBombs.length>=48)return false;e.fireflyBombs.push({x:p.x,y:p.y,damage,r:radius,life:delay,max:delay,kind,generation});return true;}
function burst(e,m,p,radius,damage,generation=0){const c=e.skillData(21);if(e.fx.filter(f=>f.kind==='fireflyBlast').length<14)e.fx.push({kind:'fireflyBlast',x:p.x,y:p.y,r:radius,life:.28,max:.28,color:'#a6ffe0'});for(const a of e.enemies)if(live(e,a)&&distance(a,p)<radius+(a.r||16))e.companionHit(a,damage,{...c,extra:true,fireflySplash:true,fireflyGeneration:generation});}
export function fireflyCast(e,m,a){const c=e.skillData(21),target=fireflyTarget(e,m)||a;const n=2+r(m,'ember');for(let i=0;i<n;i++){const phi=i*2.4;queueAirstrike(e,{x:target.x+Math.cos(phi)*(i?90:0),y:target.y+Math.sin(phi)*(i?90:0)},c.damage*(1.4+.2*r(m,'scorch')),170+20*r(m,'scorch'),.3+i*.08);}if(m.flightUntil>e.time)m.cd*=.65;}
export function fireflySlam(e,m){const c=e.skillData(21),rain=r(m,'firefall');burst(e,m,m,330+35*r(m,'scorch'),c.damage*5.5);m.flightUntil=e.time+3+1.5*r(m,'combustion');if(rain){const a=fireflyTarget(e,m,1100)||m,theta=Math.atan2(a.y-m.y,a.x-m.x);for(let i=0;i<6+4*rain;i++){const lane=(i%3-1)*155,step=(Math.floor(i/3)-1)*175;queueAirstrike(e,{x:a.x+Math.cos(theta)*step-Math.sin(theta)*lane,y:a.y+Math.sin(theta)*step+Math.cos(theta)*lane},c.damage*(2+.5*rain),190+15*rain,.22+i*.09,'cluster');}}
}
export function fireflySplash(e,m,a,c){if(c.fireflySplash||c.fireflySplashDone)return;const radius=145+25*r(m,'scorch'),skill=e.skillData(21);burst(e,m,a,radius,skill.damage*(.65+.15*r(m,'ember')),c.fireflyGeneration||0);}
export function fireflyDeath(e,a,meta){if(!e.combat||!e.team.includes(21)||meta.owner!==21)return;const m=e.members[21];m.fuel=Math.min(8,(m.fuel||0)+.35+.1*r(m,'jet'));if(r(m,'combustion')&&m.ascRun?.style==='fire')m.ascRun.life=Math.min(6,m.ascRun.life+.2);if(r(m,'superbreak')&&a.broken>0&&(meta.fireflyGeneration||0)<2&&(m.chainBombAt||0)<=e.time){m.chainBombAt=e.time+.09;const next=fireflyTarget(e,a,450);if(next)queueAirstrike(e,next,e.skillData(21).damage*(2+r(m,'superbreak')),210+25*r(m,'superbreak'),.2,'rupture',(meta.fireflyGeneration||0)+1);}}
export function updateFirefly(e,dt){e.fireflyBombs??=[];if(!e.combat||!e.team.includes(21)){e.fireflyBombs=[];return;}const m=e.members[21];if(m.ascRun?.style==='fire'&&(m.strafeBombAt||0)<=e.time){m.strafeBombAt=e.time+.32;const c=e.skillData(21);queueAirstrike(e,m,c.damage*(1.8+.4*r(m,'combustion')),220+20*r(m,'combustion'),.18,'strafe');}
 // Work from a snapshot: impact-triggered chain bombs wait for the next update.
 const active=e.fireflyBombs.splice(0);for(const b of active){b.life-=dt;if(b.life>0){e.fireflyBombs.push(b);continue;}burst(e,m,b,b.r,b.damage,b.generation);if(b.kind==='cluster'&&r(m,'firefall')>1){const count=r(m,'firefall');for(let i=0;i<count;i++){const angle=i*Math.PI*2/count;queueAirstrike(e,{x:b.x+Math.cos(angle)*100,y:b.y+Math.sin(angle)*100},b.damage*.5,125,.18,'fragment',b.generation);}}}if(e.fireflyBombs.length>48)e.fireflyBombs.length=48;}
export function clearFirefly(e){e.fireflyBombs=[];const m=e.members[21];if(m){m.flightUntil=0;m.strafeBombAt=0;m.chainBombAt=0;}}
export function drawFirefly(e,c,at){for(const b of e.fireflyBombs||[]){at(b.x,b.y,4,()=>{const t=1-b.life/b.max;c.strokeStyle='#a9efce';c.globalAlpha=.55;c.lineWidth=1;const s=17;for(const k of [-1,1]){c.beginPath();c.moveTo(k*s,-s*.6);c.lineTo(k*s,s*.6);c.stroke();}c.globalAlpha=.9;c.lineWidth=b.kind==='cluster'?4:3;c.beginPath();c.moveTo(-18*(1-t),-180*(1-t)-20);c.lineTo(0,-160*(1-t));c.stroke();});}for(const f of e.fx){if(f.kind!=='fireflyBlast')continue;at(f.x,f.y,8,()=>{c.globalAlpha=.6*f.life/f.max;c.strokeStyle=f.color;c.lineWidth=3;const size=Math.min(110,f.r*.36);for(let i=0;i<8;i++){const a=i*Math.PI/4;c.beginPath();c.moveTo(Math.cos(a)*15,Math.sin(a)*10);c.lineTo(Math.cos(a)*size,Math.sin(a)*size*.7);c.stroke();}c.fillStyle='#ffe4a9';c.fillRect(-4,-4,8,8);});}}
